//! Access to `argv`, matching the C++ program's view of it.

/// The process arguments, including `argv[0]`, so that indices line up with the
/// C++ `argv` and `args().len()` equals `argc`.
///
/// This is [`std::env::args`] with one deliberate difference: `std::env::args`
/// panics if any argument is not valid UTF-8, whereas C++ hands `main` raw bytes
/// and never fails. Going through [`std::env::args_os`] and replacing invalid
/// bytes keeps the C++ behaviour — such bytes are not digits, so the parse
/// outcome is the same one `std::stoi` would reach.
pub fn args() -> Vec<String> {
    std::env::args_os()
        .map(|arg| arg.to_string_lossy().into_owned())
        .collect()
}

/// The `index`-th argument (`argv[index]`), or `None` when `argc <= index`.
pub fn arg(index: usize) -> Option<String> {
    args().into_iter().nth(index)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn argv_zero_is_always_present() {
        // The test harness is itself a process, so `argv[0]` exists.
        assert!(!args().is_empty());
        assert!(arg(0).is_some());
        assert_eq!(arg(usize::MAX), None);
    }
}

//! A faithful re-implementation of C++'s `std::stoi`.
//!
//! `std::stoi(str)` is specified as a `std::strtol` call with base 10 whose
//! result is narrowed to `int`. That means it is *prefix* parsing, not
//! whole-string parsing, and it reports failure by throwing:
//!
//! * leading whitespace (`" \t\n\v\f\r"`) is skipped;
//! * an optional `+` or `-` sign may follow;
//! * decimal digits are then consumed for as long as they appear, and the rest
//!   of the string is ignored — `"3abc"` is `3`, `"12.9"` is `12`, `"1e3"` is
//!   `1`, and `"0x10"` is `0` (base 10 gives `0x` no special meaning);
//! * if no digit was consumed it throws `std::invalid_argument`;
//! * if the value does not fit in `int` it throws `std::out_of_range`.
//!
//! Both exceptions carry `what() == "stoi"`.

/// Why a [`stoi`] call failed, mirroring the exception C++ would throw.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum StoiError {
    /// No digits were found: C++ throws `std::invalid_argument`.
    InvalidArgument,
    /// Digits were found but the value does not fit in `int`: C++ throws
    /// `std::out_of_range`.
    OutOfRange,
}

impl StoiError {
    /// The fully qualified C++ exception type this corresponds to.
    pub fn exception_type(self) -> &'static str {
        match self {
            StoiError::InvalidArgument => "std::invalid_argument",
            StoiError::OutOfRange => "std::out_of_range",
        }
    }

    /// The exception's `what()` string, which for `std::stoi` is the function
    /// name.
    pub fn what(self) -> &'static str {
        "stoi"
    }
}

impl std::fmt::Display for StoiError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}: {}", self.exception_type(), self.what())
    }
}

impl std::error::Error for StoiError {}

/// True for the characters C++'s `isspace` accepts in the default "C" locale.
fn is_cxx_space(c: char) -> bool {
    matches!(c, ' ' | '\t' | '\n' | '\u{b}' | '\u{c}' | '\r')
}

/// Parses a leading `int` out of `s` exactly as C++'s `std::stoi(s)` does.
///
/// # Examples
///
/// ```ignore
/// assert_eq!(stoi("42"), Ok(42));
/// assert_eq!(stoi("  -7xyz"), Ok(-7));
/// assert_eq!(stoi("0x10"), Ok(0));
/// assert_eq!(stoi("abc"), Err(StoiError::InvalidArgument));
/// assert_eq!(stoi("2147483648"), Err(StoiError::OutOfRange));
/// ```
pub fn stoi(s: &str) -> Result<i32, StoiError> {
    stoi_with_pos(s).map(|(value, _)| value)
}

/// Like [`stoi`], but also reports how many bytes were consumed — the value
/// `std::stoi` writes through its optional `pos` out-parameter.
pub fn stoi_with_pos(s: &str) -> Result<(i32, usize), StoiError> {
    let bytes = s.as_bytes();
    let mut i = 0;

    while i < bytes.len() && is_cxx_space(bytes[i] as char) {
        i += 1;
    }

    let negative = match bytes.get(i) {
        Some(b'-') => {
            i += 1;
            true
        }
        Some(b'+') => {
            i += 1;
            false
        }
        _ => false,
    };

    let digits_start = i;
    // Accumulate the magnitude. `strtol` keeps scanning digits after it has
    // overflowed (so the reported end position still covers them all) and then
    // reports a range error, so overflow is latched rather than returned early.
    let mut magnitude: u64 = 0;
    let mut overflowed = false;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        let digit = u64::from(bytes[i] - b'0');
        if !overflowed {
            match magnitude.checked_mul(10).and_then(|m| m.checked_add(digit)) {
                Some(next) => magnitude = next,
                None => overflowed = true,
            }
        }
        i += 1;
    }

    if i == digits_start {
        // Not a single digit: `strtol` consumed nothing, so `stoi` throws.
        return Err(StoiError::InvalidArgument);
    }

    // `int` is two's-complement 32-bit, so the negative range extends one
    // further than the positive one.
    let limit: u64 = if negative {
        i32::MAX as u64 + 1
    } else {
        i32::MAX as u64
    };
    if overflowed || magnitude > limit {
        return Err(StoiError::OutOfRange);
    }

    let value = if negative {
        (magnitude as i64).wrapping_neg() as i32
    } else {
        magnitude as i32
    };
    Ok((value, i))
}

/// Reproduces what a C++ program does when an exception escapes `main`.
///
/// The runtime prints the `terminate called after throwing …` banner on stderr
/// and calls `std::abort`, which leaves the process killed by `SIGABRT` (shell
/// exit status 134). [`std::process::abort`] raises the same signal, so the port
/// is observably identical down to the exit status.
pub fn terminate_with_uncaught_exception(error: StoiError) -> ! {
    eprint!(
        "terminate called after throwing an instance of '{}'\n  what():  {}\n",
        error.exception_type(),
        error.what()
    );
    std::process::abort()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn plain_integers() {
        assert_eq!(stoi("0"), Ok(0));
        assert_eq!(stoi("11"), Ok(11));
        assert_eq!(stoi("007"), Ok(7));
        assert_eq!(stoi("2147483647"), Ok(i32::MAX));
        assert_eq!(stoi("-2147483648"), Ok(i32::MIN));
        assert_eq!(stoi("-0"), Ok(0));
        assert_eq!(stoi("+4"), Ok(4));
    }

    #[test]
    fn leading_whitespace_is_skipped() {
        assert_eq!(stoi(" 7"), Ok(7));
        assert_eq!(stoi("\t9"), Ok(9));
        assert_eq!(stoi("\n9"), Ok(9));
        assert_eq!(stoi("\u{b}9"), Ok(9));
        assert_eq!(stoi("\u{c}9"), Ok(9));
        assert_eq!(stoi("\r9"), Ok(9));
        assert_eq!(stoi("  \t -5"), Ok(-5));
    }

    #[test]
    fn parsing_stops_at_the_first_non_digit() {
        assert_eq!(stoi("3abc"), Ok(3));
        assert_eq!(stoi("12.9"), Ok(12));
        assert_eq!(stoi("1e3"), Ok(1));
        assert_eq!(stoi("0x10"), Ok(0));
        assert_eq!(stoi("1 2"), Ok(1));
        assert_eq!(stoi("5-3"), Ok(5));
        assert_eq!(stoi("2147483647x"), Ok(i32::MAX));
    }

    #[test]
    fn missing_digits_is_invalid_argument() {
        for s in ["", " ", "  ", "abc", "x1", ".5", "-x", "+", "-", "--5", "+-5", "  +  7"] {
            assert_eq!(stoi(s), Err(StoiError::InvalidArgument), "input {:?}", s);
        }
    }

    #[test]
    fn out_of_int_range_is_out_of_range() {
        for s in [
            "2147483648",
            "-2147483649",
            "4294967296",
            "9223372036854775808",
            "999999999999999999999",
            "-99999999999999999999",
            "2147483648abc",
        ] {
            assert_eq!(stoi(s), Err(StoiError::OutOfRange), "input {:?}", s);
        }
    }

    #[test]
    fn reported_position_covers_the_consumed_prefix() {
        assert_eq!(stoi_with_pos("42"), Ok((42, 2)));
        assert_eq!(stoi_with_pos("  -7xyz"), Ok((-7, 4)));
        assert_eq!(stoi_with_pos("0x10"), Ok((0, 1)));
    }

    #[test]
    fn error_messages_match_the_cxx_runtime() {
        assert_eq!(StoiError::InvalidArgument.exception_type(), "std::invalid_argument");
        assert_eq!(StoiError::OutOfRange.exception_type(), "std::out_of_range");
        assert_eq!(StoiError::OutOfRange.what(), "stoi");
    }
}

//! A from-scratch persistent vector, re-implementing the `immer::vector`
//! contract with nothing but the standard library.
//!
//! * [`vector::Vector`] — the immutable vector itself.
//! * [`node`] — the bit-partitioned trie nodes it is built from.
//! * [`iter`] — `O(n)` forward iteration.

pub mod iter;
pub mod node;
pub mod vector;

// `self::` keeps this resolvable under both the 2015 and 2021 editions, so the
// entry file builds with a bare `rustc test11.rs` as well as with Cargo.
pub use self::vector::Vector;
=== node ===
//! Trie node representation for the persistent vector.
//!
//! `immer::vector` (like Clojure's `PersistentVector` and the RRB-tree family it
//! is derived from) stores its elements in a *bit-partitioned vector trie*: a
//! tree of fixed-width nodes where the radix-`B` digits of an element's index
//! spell out the path from the root down to the leaf holding it.
//!
//! With a branching factor of `B = 32` each level consumes `BITS = 5` bits of
//! the index, so lookup is `O(log32 n)` — effectively constant for any vector
//! that fits in memory — and `push_back` only has to copy the `O(log32 n)` nodes
//! along one root-to-leaf path. Every untouched node is shared with the previous
//! version through reference counting, which is what makes the structure
//! *persistent*: the old vector stays alive, valid, and unchanged.

use std::rc::Rc;

/// Number of index bits consumed per trie level.
pub const BITS: u32 = 5;

/// Branching factor of the trie: `2^BITS` children per inner node.
pub const BRANCHING: usize = 1 << BITS;

/// Mask selecting the index bits belonging to a single level.
pub const MASK: usize = BRANCHING - 1;

/// A node of the vector trie.
///
/// Nodes are always reached through an [`Rc`], which is what implements the
/// structural sharing between vector versions. A node is immutable once built;
/// "modifying" a vector means building fresh nodes along one path and sharing
/// every sibling subtree with the source vector.
///
/// Invariants (upheld by [`super::vector::Vector`]):
///
/// * A node at level `l > 0` is always [`Node::Inner`]; a node at level `0` is
///   always [`Node::Leaf`].
/// * Children are packed left-to-right with no gaps, so an inner node's
///   `children.len()` is exactly its number of populated slots.
/// * `children.len() <= BRANCHING` and `elems.len() <= BRANCHING`.
/// * Every leaf that lives *inside the trie* is completely full
///   (`elems.len() == BRANCHING`); a partially filled trailing leaf is held
///   outside the trie, in the vector's tail.
pub enum Node<T> {
    /// Interior node: `BRANCHING`-way fan-out to child nodes one level down.
    Inner(Vec<Rc<Node<T>>>),
    /// Leaf node: a chunk of up to `BRANCHING` consecutive elements.
    Leaf(Vec<T>),
}

impl<T> Node<T> {
    /// A fresh inner node with no children.
    pub fn empty_inner() -> Rc<Node<T>> {
        Rc::new(Node::Inner(Vec::new()))
    }

    /// The children of an inner node.
    ///
    /// # Panics
    ///
    /// Panics if called on a leaf, which would mean the level bookkeeping in
    /// [`super::vector::Vector`] had gone wrong.
    pub fn children(&self) -> &Vec<Rc<Node<T>>> {
        match self {
            Node::Inner(children) => children,
            Node::Leaf(_) => unreachable!("expected an inner node, found a leaf"),
        }
    }

    /// The elements of a leaf node.
    ///
    /// # Panics
    ///
    /// Panics if called on an inner node.
    pub fn elems(&self) -> &[T] {
        match self {
            Node::Leaf(elems) => elems,
            Node::Inner(_) => unreachable!("expected a leaf, found an inner node"),
        }
    }

    /// Whether this node is a leaf.
    pub fn is_leaf(&self) -> bool {
        matches!(self, Node::Leaf(_))
    }
}

/// Builds the single-child chain that hangs a finished leaf at depth `level`.
///
/// When a new leaf has to be attached somewhere the trie has no branch yet, the
/// intervening inner nodes must be created: `new_path` returns a spine of
/// one-child nodes from `level` down to the leaf. `level == 0` means "the leaf
/// belongs right here", so the node is returned as-is.
pub fn new_path<T>(level: u32, node: Rc<Node<T>>) -> Rc<Node<T>> {
    debug_assert!(node.is_leaf(), "new_path always terminates in a leaf");
    if level == 0 {
        node
    } else {
        Rc::new(Node::Inner(vec![new_path(level - BITS, node)]))
    }
}

